const converseSteps = (o='O',p='P',m='M',n='N') => [
  B(`The perpendicular conditions make △${o}${p}${m} and △${o}${p}${n} right triangles.`,`由兩個垂直條件，△${o}${p}${m} 和 △${o}${p}${n} 均為直角三角形。`),
  B(`${o}${p}=${o}${p} is the common hypotenuse, and ${p}${m}=${p}${n} is given.`,`${o}${p}=${o}${p} 為公共斜邊，而 ${p}${m}=${p}${n} 是已知。`),
  B(`Thus △${o}${p}${m}≅△${o}${p}${n} by HL.`,`所以 △${o}${p}${m}≅△${o}${p}${n}（HL）。`),
  B(`Corresponding angles give ∠${m}${o}${p}=∠${p}${o}${n}.`,`由對應角相等，得 ∠${m}${o}${p}=∠${p}${o}${n}。`),
  B(`Since ${p} is inside the angle, ${o}${p} is its internal bisector.`,`因為 ${p} 在角內，所以 ${o}${p} 是該角的內角平分線。`),
];
const converseHints = (o='O',p='P',m='M',n='N') => [
  B(`Identify the right angle in each triangle and the opposite side ${o}${p}.`,`找出兩個直角及其對邊 ${o}${p}。`),
  B(`For HL, use common hypotenuse ${o}${p} and the given equal legs ${p}${m}, ${p}${n}.`,`HL 使用公共斜邊 ${o}${p} 及已知等長直角邊 ${p}${m}、${p}${n}。`),
  B(`Congruence gives equal angles at ${o}; retain the condition that ${p} is inside the angle.`,`全等推出 ${o} 點等角；仍要保留 ${p} 在角內的條件。`),
];
const converseRubric=[B('State both right triangles and identify the common hypotenuse.','寫出兩個直角三角形並指出公共斜邊。'),B('Use the given equal legs and HL.','使用已知等直角邊及 HL。'),B('Deduce equal vertex angles and retain the interior condition.','推出頂點等角，並保留角內條件。'),validProof];
